INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Unicast immer die schnellste Kommunikationsart?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt vom Netzwerk ab"}, {"text": "Ja", "correct": false, "because": "Nicht universell schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal definiert Unicast am besten?', 3, '[{"text": "1-zu-1-Verbindung", "correct": true, "because": "Ein Sender, ein Empfänger"}, {"text": "Gruppenkommunikation", "correct": false, "because": "Das ist Multicast"}, {"text": "Nächster Empfänger", "correct": false, "because": "Das ist Anycast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle nutzen Unicast?', 5, '[{"text": "TCP", "correct": true, "because": "Verbindungsorientiert"}, {"text": "HTTP", "correct": true, "because": "Client-Server"}, {"text": "IGMP", "correct": false, "because": "Für Multicast"}, {"text": "RIP", "correct": false, "because": "Routing, nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unicast nutzt eine eindeutige Adresse. b) Es ist für Broadcast gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Broadcast ist anders"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Unicast-Kommunikation?', 4, '[{"text": "Zieladresse", "correct": false, "because": "Muss eindeutig sein"}, {"text": "Protokoll", "correct": false, "because": "Definiert Übertragung"}, {"text": "Gruppenzugehörigkeit", "correct": true, "because": "Multicast-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Unicast Bandbreite spart?', 2, '[{"text": "Nein", "correct": true, "because": "Nur direkte Verbindung"}, {"text": "Ja", "correct": false, "because": "Keine Gruppenoptimierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wähle ich für Unicast?', 3, '[{"text": "Eindeutige IP", "correct": true, "because": "Einzelgerät ansprechen"}, {"text": "FF02::1", "correct": false, "because": "Multicast-Adresse"}, {"text": "255.255.255.255", "correct": false, "because": "Broadcast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat Unicast?', 5, '[{"text": "Direkte Kommunikation", "correct": true, "because": "1-zu-1"}, {"text": "Eindeutige Adressierung", "correct": true, "because": "Ziel spezifisch"}, {"text": "Alle Geräte erreichen", "correct": false, "because": "Nicht Broadcast"}, {"text": "Nächstes Gerät", "correct": false, "because": "Nicht Anycast"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Unicast ist Standard bei TCP. b) Es nutzt Multicast-Adressen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Multicast"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Unicast?', 4, '[{"text": "Ziel-IP", "correct": false, "because": "Kern der Adressierung"}, {"text": "Transportprotokoll", "correct": false, "because": "Definiert Übertragung"}, {"text": "Gruppen-ID", "correct": true, "because": "Multicast-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Unicast für Gruppen geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Nur 1-zu-1"}, {"text": "Ja", "correct": false, "because": "Gruppen sind Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode nutze ich für direkte Datenübertragung?', 4, '[{"text": "Unicast", "correct": true, "because": "Einzelverbindung"}, {"text": "Multicast", "correct": false, "because": "Gruppenbezogen"}, {"text": "Broadcast", "correct": false, "because": "Alle erreichen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Unicast ineffizient ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Effizient für Einzelziele"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Unicast?', 3, '[{"text": "Eindeutige Adresse", "correct": true, "because": "Zielgenauigkeit"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Netzwerkabhängig"}, {"text": "Multicast-Gruppe", "correct": false, "because": "Falsche Methode"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unicast ist punktgenau. b) Es ersetzt Multicast.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Multicast bleibt eigenständig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Unicast?', 5, '[{"text": "Präzise Zustellung", "correct": true, "because": "Einzelgerät"}, {"text": "Einfache Implementierung", "correct": true, "because": "Standardmethode"}, {"text": "Gruppenabdeckung", "correct": false, "because": "Nicht Unicast"}, {"text": "Bandbreitensparend", "correct": false, "because": "Nur bei Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Unicast unwichtig?', 3, '[{"text": "Zieladresse", "correct": false, "because": "Kern der Methode"}, {"text": "Protokollwahl", "correct": false, "because": "Definiert Übertragung"}, {"text": "Gruppenmanagement", "correct": true, "because": "Multicast-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt Unicast mehrere Empfänger?', 3, '[{"text": "Nein", "correct": true, "because": "Nur 1-zu-1"}, {"text": "Ja", "correct": false, "because": "Verwechselt mit Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Unicast für Streaming geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Für Einzelverbindungen"}, {"text": "Nein", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich für eine direkte Serververbindung?', 4, '[{"text": "Unicast", "correct": true, "because": "Punkt-zu-Punkt"}, {"text": "Multicast", "correct": false, "because": "Gruppenorientiert"}, {"text": "Anycast", "correct": false, "because": "Nächster Empfänger"}]');
